package br.com.example.davidarchanjo.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import javax.servlet.http.HttpServletRequest; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(BusinessException.class) public ResponseEntity<Map<String,Object>> business(BusinessException e,HttpServletRequest r){Map<String,Object>m=new LinkedHashMap<>();m.put("timestamp",Instant.now());m.put("status",e.status.value());m.put("errorCode",e.code);m.put("message",e.getMessage());m.put("path",r.getRequestURI());return ResponseEntity.status(e.status).body(m);}}
